        left = Math.round(ax - w / 2);
        left = Math.max(EDGE_MARGIN, Math.min(vw - w - EDGE_MARGIN, left));
        top = side === "below"
          ? Math.round(ay + ARROW_GAP)
          : Math.round(ay - ARROW_GAP - h);
