        // center. Slide the arrow so its tip still lands on ax.
        var arrowX = ax - left;
        arrowX = Math.max(ARROW_SIZE + 6, Math.min(w - ARROW_SIZE - 6, arrowX));
        arrowOffset = arrowX + "px";
