    // We can't tell from the renderer whether a click registered with main
    // (invoke() always returns a promise — it's whether the CLICK EVENT
    // reached us that's uncertain). So: re-arm on a timeout. If the overlay
    // hides, the timeout runs against a hidden DOM — harmless. Same 3s as
    // the CU pill's stop button (overlay/html.ts:291-294).
    function withRearm(btns, fn) {
      for (var i = 0; i < btns.length; i++) btns[i].disabled = true;
      fn();
      setTimeout(function() {
        for (var i = 0; i < btns.length; i++) btns[i].disabled = false;
      }, 3000);
    }

    nextBtn.addEventListener("click", function() {
      withRearm([nextBtn], function() { window.cuTeach.next(); });
      // Controller resolves the pending promise → handleTeachStep calls
      // onTeachWorking → cu-teach:working → spinner. No optimistic local
      // flip — state machine stays on one side.
    });

    function doExit() {
      withRearm([exitBtn, exitBtnWorking], function() {
        window.cuTeach.exit();
      });
      // Overlay hide happens via teachModeChanged → cu-teach:hide.
    }
    exitBtn.addEventListener("click", doExit);
    exitBtnWorking.addEventListener("click", doExit);
